    void refundGrants(){financeGrants();for(UUID who:java.util.List.of(STAFF,B))for(String permission:java.util.List.of("refund.synthetic.read","refund.synthetic.review","refund.synthetic.destination.verify","refund.synthetic.approve","refund.synthetic.execute","refund.synthetic.reconcile"))jdbc.sql("INSERT INTO cinenest_identity.access_grant VALUES(:id,:a,:p,'VENUE',:v,'ACTIVE',clock_timestamp()-INTERVAL '1 minute',clock_timestamp()+INTERVAL '1 hour',0)").param("id",UUID.randomUUID()).param("a",who).param("p",permission).param("v",VA).update();}
    record RefundCase(Browser customer,Browser reviewer,Browser executor,Map<String,Object> request,Map<String,Object> credit,Map<String,Object> refund){}
    RefundCase refundCase(long amount)throws Exception{refundGrants();var customer=signedIn("customer-a");var reviewer=signedIn("staff");var executor=signedIn("customer-b");var request=bank(customer);var credit=credit(reviewer,"SYNTHETIC-BANK-50000");request=match(executor,request,credit);var body=financial(((Number)request.get("revision")).longValue());body.put("creditId",credit.get("id"));body.put("amountMinor",Long.toString(amount));body.put("currency","LKR");var refund=json(write(customer,"POST",bankPath(request)+"/refunds",JSONObjectUtils.toJSONString(body)));return new RefundCase(customer,reviewer,executor,request,credit,refund);}
    String refundRoot(Map<String,Object> r){return "/api/admin/venues/"+VA+"/refunds/"+r.get("id");}
    Map<String,Object> refundWrite(Browser actor,Map<String,Object> refund,String suffix,Map<String,Object> fields)throws Exception{var body=financial(((Number)refund.get("revision")).longValue());body.putAll(fields);return json(write(actor,"POST",refundRoot(refund)+suffix,JSONObjectUtils.toJSONString(body)));}
    Map<String,Object> approveRefund(RefundCase c)throws Exception{var r=refundWrite(c.reviewer(),c.refund(),"/decisions",Map.of("action","REVIEW"));r=refundWrite(c.reviewer(),r,"/destination-verifications",Map.of("destinationReference","SYNTHETIC-PAYER-50000"));return refundWrite(c.reviewer(),r,"/decisions",Map.of("action","APPROVE"));}
    Map<String,Object> outgoing(RefundCase c,Map<String,Object> r,String fixture)throws Exception{var attempts=(java.util.List<Map<String,Object>>)r.get("attempts");r=refundWrite(c.executor(),r,"/attempts/"+attempts.getLast().get("id")+"/evidence",Map.of("fixtureKey",fixture));assertThat(r.get("state")).isEqualTo("AWAITING_EVIDENCE");return refundWrite(c.reviewer(),r,"/attempts/"+attempts.getLast().get("id")+"/evidence",Map.of("fixtureKey",fixture));}
    @Test void refundApprovalIsNotRepaymentAndConfirmedReturnReplacesReservationOnce()throws Exception{
      var c=refundCase(100);var r=approveRefund(c);assertThat(r.get("state")).isEqualTo("APPROVED");assertThat(r.get("realRepayment")).isEqualTo(false);assertThat(r.get("availableMinor")).isEqualTo("49900");r=refundWrite(c.executor(),r,"/attempts",Map.of());r=outgoing(c,r,"SYNTHETIC-CONFIRMED");assertThat(r.get("state")).isEqualTo("SIMULATED_CONFIRMED");assertThat(r.get("availableMinor")).isEqualTo("49900");assertThat(c.customer().get("/api/refunds/"+r.get("id")).body()).doesNotContain("destinationReference","executor_id","manifest_hash");assertThat(jdbc.sql("SELECT count(*) FROM cinenest_booking.booking").query(Integer.class).single()).isZero();assertThat(jdbc.sql("SELECT count(*) FROM cinenest_payments.incoming_payment_credit").query(Integer.class).single()).isEqualTo(1);
    }
    @Test void unknownRefundCannotResendOrWithdrawAndReconciliationSurvivesNewSession()throws Exception{
      var c=refundCase(50000);var r=refundWrite(c.executor(),approveRefund(c),"/attempts",Map.of());r=outgoing(c,r,"SYNTHETIC-UNKNOWN");assertThat(r.get("availableMinor")).isEqualTo("0");var body=financial(((Number)r.get("revision")).longValue());assertThat(write(c.executor(),"POST",refundRoot(r)+"/attempts",JSONObjectUtils.toJSONString(body)).statusCode()).isEqualTo(409);body.put("action","WITHDRAW");assertThat(write(c.reviewer(),"POST",refundRoot(r)+"/decisions",JSONObjectUtils.toJSONString(body)).statusCode()).isEqualTo(409);var recovered=json(signedIn("staff").get("/api/refunds/"+r.get("id")));assertThat(recovered.get("resolution")).isEqualTo("RECONCILIATION_REQUIRED");r=reconcileRefund(c,recovered,"SYNTHETIC-CONFIRMED");assertThat(r.get("state")).isEqualTo("SIMULATED_CONFIRMED");assertThat(r.get("availableMinor")).isEqualTo("0");
    }
