    record AccessCase(Browser customer,Browser staff, Browser allocator,Map<String,Object> request,Map<String,Object> credit,UUID booking){}
    AccessCase accessCase()throws Exception{financeGrants();var customer=signedIn("customer-a");var staff=signedIn("staff");var allocator=signedIn("customer-b");var r=bank(customer);var c=credit(staff,"SYNTHETIC-BANK-50000");r=match(allocator,r,c);var confirmed=json(allocateCredit(allocator,r,c,Long.parseLong(r.get("amountMinor").toString())));for(String permission:java.util.List.of("access.synthetic.read","access.synthetic.issue","access.synthetic.reveal","access.synthetic.attempt"))jdbc.sql("INSERT INTO cinenest_identity.access_grant VALUES(:id,:a,:p,'SELF',NULL,'ACTIVE',clock_timestamp()-INTERVAL '1 minute',clock_timestamp()+INTERVAL '2 days',0)").param("id",UUID.randomUUID()).param("a",A).param("p",permission).update();for(String permission:java.util.List.of("access.synthetic.review","access.synthetic.revoke","access.synthetic.simulate"))grantTo(STAFF,VA,permission);return new AccessCase(customer,staff,allocator,r,c,UUID.fromString(confirmed.get("bookingId").toString()));}
    String accessPath(AccessCase c){return "/api/bookings/"+c.booking()+"/access";}
    String accessAdmin(Map<String,Object> r){return "/api/admin/venues/"+VA+"/access/credentials/"+r.get("id");}
    Map<String,Object> accessBody(Map<String,Object> r){var b=financial(r.containsKey("revision")?((Number)r.get("revision")).longValue():0);b.put("bookingRevision",1);b.put("expectedVersion",r.getOrDefault("version",0));return b;}
    Map<String,Object> issueAccess(AccessCase c)throws Exception{var b=accessBody(Map.of());b.put("mode","ISSUE");return json(write(c.customer(),"POST",accessPath(c)+"/credentials",JSONObjectUtils.toJSONString(b)));}
    Map<String,Object> simulateAccess(AccessCase c,Map<String,Object> r,String fixture,boolean reconcile)throws Exception{var b=accessBody(r);b.put("operationId",r.get("operationId"));b.put("credentialVersion",r.get("version"));b.put("fixture",fixture);b.put("reconcile",reconcile);return json(write(c.staff(),"POST",accessAdmin(r)+"/simulations",JSONObjectUtils.toJSONString(b)));}
    Object accessClock(AccessCase c,long seconds)throws Exception{var b=new org.springframework.transaction.support.TransactionTemplate(transactions).execute(t->context.getBean(com.cinenest.booking.BookingAccess.class).lock(c.booking()).orElseThrow());return com.cinenest.access.internal.AccessFaults.clock(context.getBean("accessService"),b.start().plusSeconds(seconds));}
    void restoreAccessClock(Object repo)throws Exception{com.cinenest.access.internal.AccessFaults.restore(context.getBean("accessService"),repo);}
    @Test void accessUsesConfirmedPurchasedContextNotConsumedHoldAndProtectsStoredMaterial(CapturedOutput output)throws Exception{var c=accessCase();var r=issueAccess(c);assertThat(r.get("state")).isEqualTo("SCHEDULED");assertThat(r.get("doorControlled")).isEqualTo(false);assertThat(c.customer().get(accessPath(c)).headers().firstValue("Cache-Control")).contains("no-store");assertThat(jdbc.sql("SELECT state FROM cinenest_booking.reservation_hold").query(String.class).single()).isEqualTo("CONSUMED");var stored=jdbc.sql("SELECT token_hash,protected_secret,key_version FROM cinenest_access.access_credential").query().singleRow();assertThat((byte[])stored.get("token_hash")).hasSize(32);assertThat((byte[])stored.get("protected_secret")).hasSizeGreaterThan(43);assertThat(c.staff().get(accessAdmin(r)).body()).doesNotContain("protected_secret","token_hash","token\"");assertThat(output.getAll()).doesNotContain(stored.get("protected_secret").toString());}
