    @Test void accessOldSecretCannotEnterNewVersionAndNeverAppearsInLogsOrCommandAudit(CapturedOutput output)throws Exception{var c=accessCase();var r=simulateAccess(c,issueAccess(c),"SYNTHETIC-INSTALLED",false);Object repo=accessClock(c,0);try{r=json(c.customer().get(accessPath(c)));var old=json(write(c.customer(),"POST",accessPath(c)+"/credentials/"+r.get("id")+"/reveal",JSONObjectUtils.toJSONString(accessBody(r))));String token=old.get("token").toString();var b=accessBody(old);b.put("mode","REISSUE");var next=simulateAccess(c,json(write(c.customer(),"POST",accessPath(c)+"/credentials",JSONObjectUtils.toJSONString(b))),"SYNTHETIC-INSTALLED",false);b=accessBody(next);b.put("token",token);b.put("credentialId",next.get("id"));assertThat(write(c.customer(),"POST",accessPath(c)+"/simulated-attempts",JSONObjectUtils.toJSONString(b)).statusCode()).isEqualTo(403);b=accessBody(old);b.put("token",token);b.put("credentialId",old.get("id"));assertThat(write(c.customer(),"POST",accessPath(c)+"/simulated-attempts",JSONObjectUtils.toJSONString(b)).statusCode()).isEqualTo(409);for(String table:java.util.List.of("access_command","access_audit","access_attempt"))assertThat(jdbc.sql("SELECT COALESCE(string_agg(row_to_json(t)::text,''),'') FROM cinenest_access."+table+" t").query(String.class).single()).doesNotContain(token);assertThat(output.getAll()).doesNotContain(token);}finally{restoreAccessClock(repo);}}
