    static final UUID LIGHT=id("synthetic-light");
    String iotRoot(){return "/api/admin/venues/"+VA+"/iot/devices/"+LIGHT;}
    void iotGrants(){for(String p:java.util.List.of("read","command","simulate","reconcile"))grantTo(STAFF,VA,"iot.synthetic."+p);}
    java.time.Instant iotTime(AccessCase c){return new org.springframework.transaction.support.TransactionTemplate(transactions).execute(t->context.getBean(com.cinenest.booking.BookingAccess.class).lock(c.booking()).orElseThrow().start().plusSeconds(1));}
    Object iotClock(AccessCase c)throws Exception{return com.cinenest.iot.internal.IotFaults.clock(context.getBean("iotService"),iotTime(c));}
    void iotRestore(Object r)throws Exception{com.cinenest.iot.internal.IotFaults.restore(context.getBean("iotService"),r);}
    AccessCase iotCase()throws Exception{var c=accessCase();simulateAccess(c,issueAccess(c),"SYNTHETIC-INSTALLED",false);iotGrants();new org.springframework.transaction.support.TransactionTemplate(transactions).executeWithoutResult(t->com.cinenest.iot.internal.IotFaults.register(context,LIGHT,VA,RID));return c;}
    Map<String,Object> iotBody(AccessCase c,long expected){return new HashMap<>(Map.of("bookingId",c.booking().toString(),"bookingRevision",1,"expectedRevision",expected,"commandKey",UUID.randomUUID().toString()));}
    Map<String,Object> iotWrite(Browser actor,String suffix,Map<String,Object>b)throws Exception{return json(write(actor,"POST",iotRoot()+suffix,JSONObjectUtils.toJSONString(b)));}
    Map<String,Object> iotCreate(AccessCase c)throws Exception{var b=iotBody(c,1);b.put("desired","ON");return iotWrite(c.staff(),"/commands",b);}
    @SuppressWarnings("unchecked") Map<String,Object> iotCommand(Map<String,Object>d){return ((java.util.List<Map<String,Object>>)d.get("commands")).getFirst();}
    Map<String,Object> iotOutcome(AccessCase c,Map<String,Object>d,String outcome){var cmd=iotCommand(d);var b=iotBody(c,((Number)cmd.get("revision")).longValue());b.put("correlationId",cmd.get("correlation_id"));b.put("outcome",outcome);return b;}
    @Test void iotAckNeverSetsObservationOrPhysicalReadiness()throws Exception{var c=iotCase();Object original=iotClock(c);try{var d=iotCreate(c);var cmd=iotCommand(d);d=iotWrite(c.staff(),"/commands/"+cmd.get("id")+"/simulations",iotOutcome(c,d,"ACKNOWLEDGED"));assertThat(d.get("observed")).isEqualTo("UNKNOWN");assertThat(d.get("physicalOccupancy")).isEqualTo("UNKNOWN");assertThat(d.get("physicalReadiness")).isEqualTo("UNVERIFIED");assertThat(d.get("equipmentControlled")).isEqualTo(false);assertThat(iotCommand(d).get("state")).isEqualTo("ACKNOWLEDGED");assertThat(jdbc.sql("SELECT count(*) FROM cinenest_iot.assignment").query(Integer.class).single()).isEqualTo(1);}finally{iotRestore(original);}}
    @Test void iotIndependentObservationAndOnOffRequestsRemainSeparate()throws Exception{var c=iotCase();Object original=iotClock(c);try{var d=iotCreate(c);var b=iotOutcome(c,d,"ACKNOWLEDGED");b.putAll(Map.of("observed","OFF","observationSequence",1,"observedAt",iotTime(c).toString()));d=iotWrite(c.staff(),"/commands/"+iotCommand(d).get("id")+"/simulations",b);assertThat(d.get("desired")).isEqualTo("ON");assertThat(d.get("observed")).isEqualTo("OFF");var next=iotBody(c,((Number)d.get("revision")).longValue());next.put("desired","OFF");d=iotWrite(c.staff(),"/commands",next);assertThat(d.get("desired")).isEqualTo("OFF");assertThat(d.get("observed")).isEqualTo("OFF");com.cinenest.iot.internal.IotFaults.clock(context.getBean("iotService"),iotTime(c).plusSeconds(70));d=json(c.staff().get(iotRoot()));assertThat(d.get("observed")).isEqualTo("UNKNOWN");assertThat(d.get("observationFresh")).isEqualTo(false);}finally{iotRestore(original);}}
