 Map<String,Object> opsCommand(Browser b,Map<String,Object> c,String action,Map<String,Object> extra)throws Exception{var body=opsBody(c);body.putAll(extra);return json(write(b,"POST",ops()+"/"+c.get("case_id")+"/"+action,JSONObjectUtils.toJSONString(body)));}
 Map<String,Object> opsCreate(Browser b)throws Exception{var body=opsBody(Map.of());body.put("roomId",RID.toString());return json(write(b,"POST",ops(),JSONObjectUtils.toJSONString(body)));}
 Map<String,Object> opsAsserted(Browser b)throws Exception{var c=opsCreate(b);c=opsCommand(b,c,"assignments",Map.of("assigneeId",STAFF.toString()));c=opsCommand(b,c,"acknowledgements",Map.of());for(String item:java.util.List.of("SURFACES","FLOOR"))c=opsCommand(b,c,"checklist",Map.of("item",item,"asserted",true));return opsCommand(b,c,"completion-assertions",Map.of());}
 @Test void operationsQueuePageReadRequiresIndependentCurrentVenueGrant()throws Exception{
  var b=signedIn("staff");String q=ops()+"?page=0";assertThat(new Browser().get(q).statusCode()).isEqualTo(401);
  for(String permission:java.util.List.of("booking.synthetic.read","refund.synthetic.read","access.synthetic.review"))grantTo(STAFF,VA,permission);
  assertThat(b.get(q).statusCode()).isEqualTo(403);grantTo(STAFF,VB,"operations.synthetic.read");assertThat(b.get(q).statusCode()).isEqualTo(403);
  UUID g=grantTo(STAFF,VA,"operations.synthetic.read");assertThat(b.get(q).statusCode()).isEqualTo(200);
  assertThat(b.get(ops().replace(VA.toString(),UUID.randomUUID().toString())+"?page=1").statusCode()).isEqualTo(403);
  jdbc.sql("UPDATE cinenest_identity.access_grant SET state='REVOKED' WHERE grant_id=:g").param("g",g).update();assertThat(b.get(q).statusCode()).isEqualTo(403);
  grantTo(STAFF,VA,"operations.synthetic.read");jdbc.sql("UPDATE cinenest_identity.http_session SET expiry_time=0,last_access_time=0").update();assertThat(b.get(q).statusCode()).isEqualTo(401);
 }
 @Test void operationsQueueFixedPagesAreReadOnlyAndNotPhysicalReadiness()throws Exception{
  opsGrants();var b=signedIn("staff");var first=opsCreate(b);
  for(int i=0;i<25;i++)jdbc.sql("INSERT INTO cinenest_rooms.turnover_case(case_id,venue_id,room_id,state,checklist_version,checklist,created_by) SELECT :id,venue_id,room_id,state,checklist_version,checklist,created_by FROM cinenest_rooms.turnover_case WHERE case_id=:source").param("id",UUID.randomUUID()).param("source",UUID.fromString(first.get("case_id").toString())).update();
  var before=jdbc.sql("SELECT row_to_json(c)::text FROM cinenest_rooms.turnover_case c ORDER BY case_id").query(String.class).list();
  var seen=new java.util.HashSet<Object>();for(int page=0;page<2;page++){var response=b.get(ops()+"?page="+page);var result=json(response);assertThat(response.headers().firstValue("Cache-Control").orElseThrow()).contains("no-store");assertThat(result.get("size")).isEqualTo(25L);assertThat(result).doesNotContainKey("hasNext");var items=(java.util.List<?>)result.get("items");assertThat(items).hasSize(page==0?25:1);for(Object item:items){var c=(Map<?,?>)item;assertThat(seen.add(c.get("case_id"))).isTrue();assertThat(c.get("physicalOccupancy")).isEqualTo("UNKNOWN");assertThat(c.get("physicalReadiness")).isEqualTo("UNVERIFIED");assertThat(c.get("inventoryChanged")).isEqualTo(false);}}
  assertThat(seen).hasSize(26);assertThat((java.util.List<?>)json(b.get(ops()+"?page=100000")).get("items")).isEmpty();
  for(String page:java.util.List.of("-1","100001","abc"))assertThat(b.get(ops()+"?page="+page).statusCode()).isEqualTo(400);
  assertThat(jdbc.sql("SELECT row_to_json(c)::text FROM cinenest_rooms.turnover_case c ORDER BY case_id").query(String.class).list()).isEqualTo(before);
 }
