    @Test void operationsV16UpgradePreservesExistingDataAndRepeatMigration()throws Exception{String url=System.getenv("CINENEST_DB_URL"),user=System.getenv("CINENEST_DB_USER"),password=System.getenv("CINENEST_DB_PASSWORD"),db="ops_upgrade_"+UUID.randomUUID().toString().replace("-","");String target=url.substring(0,url.lastIndexOf('/')+1)+db;try(var c=DriverManager.getConnection(url,user,password);var st=c.createStatement()){st.execute("CREATE DATABASE "+db);}try{Flyway.configure().dataSource(target,user,password).target("16").load().migrate();try(var c=DriverManager.getConnection(target,user,password);var st=c.createStatement()){st.execute("INSERT INTO cinenest_rooms.venue(venue_id,code,display_name,timezone) VALUES('00000000-0000-4000-8000-000000000001','KEEP','Retained V16','Asia/Colombo')");}var f=Flyway.configure().dataSource(target,user,password).target("17").load();assertThat(f.migrate().migrationsExecuted).isEqualTo(1);assertThat(f.migrate().migrationsExecuted).isZero();f.validate();try(var c=DriverManager.getConnection(target,user,password);var st=c.createStatement();var rs=st.executeQuery("SELECT display_name FROM cinenest_rooms.venue WHERE code='KEEP'")){assertThat(rs.next()).isTrue();assertThat(rs.getString(1)).isEqualTo("Retained V16");}}finally{try(var c=DriverManager.getConnection(url,user,password);var st=c.createStatement()){st.execute("DROP DATABASE "+db);}}}
