    void staffBookingSeed(AccessCase c,UUID booking,UUID venue,UUID owner,java.time.Instant start){
      UUID block=UUID.randomUUID(),hold=UUID.randomUUID();
      jdbc.sql("INSERT INTO cinenest_booking.inventory_block SELECT :block,:venue,room_id,:start,:end,0,:end,FALSE,'CONFIRMED',0 FROM cinenest_booking.inventory_block WHERE block_id=(SELECT block_id FROM cinenest_booking.reservation_hold WHERE hold_id=(SELECT hold_id FROM cinenest_booking.booking WHERE booking_id=:b))").param("block",block).param("venue",venue).param("start",start.atOffset(java.time.ZoneOffset.UTC)).param("end",start.plusSeconds(10800).atOffset(java.time.ZoneOffset.UTC)).param("b",c.booking()).update();
      jdbc.sql("INSERT INTO cinenest_booking.reservation_hold SELECT :hold,:owner,:block,policy_id,guests,configuration,timezone,minimum_policy_ids,created_at,expires_at,'RELEASED',revision FROM cinenest_booking.reservation_hold WHERE hold_id=(SELECT hold_id FROM cinenest_booking.booking WHERE booking_id=:b)").param("hold",hold).param("owner",owner).param("block",block).param("b",c.booking()).update();
      jdbc.sql("INSERT INTO cinenest_booking.booking VALUES(:id,:request,:hold,:owner,:venue,'SIMULATED_CONFIRMED',TRUE,clock_timestamp())").param("id",booking).param("request",UUID.randomUUID()).param("hold",hold).param("owner",owner).param("venue",venue).update();
      jdbc.sql("INSERT INTO cinenest_booking.booking_revision SELECT :id,revision,quote_id,quote_revision,quote_hash,amount_minor,currency,snapshot||jsonb_build_object('sessionStart',:start::text,'sessionEnd',:end::text) FROM cinenest_booking.booking_revision WHERE booking_id=:b ORDER BY revision DESC LIMIT 1").param("id",booking).param("start",start.toString()).param("end",start.plusSeconds(10800).toString()).param("b",c.booking()).update();
    }
