    @Test void staffBookingV18ToV19UpgradePreservesSourceAndRepeats()throws Exception{
      String url=environment.getRequiredProperty("spring.datasource.url"),user=environment.getRequiredProperty("spring.datasource.username"),password=environment.getRequiredProperty("spring.datasource.password"),database="staff_read_upgrade_"+UUID.randomUUID().toString().replace("-","");String target=url.substring(0,url.lastIndexOf('/')+1)+database;
      try(var c=DriverManager.getConnection(url,user,password);var sql=c.createStatement()){sql.execute("CREATE DATABASE "+database);}try{Flyway.configure().dataSource(target,user,password).target("18").load().migrate();try(var c=DriverManager.getConnection(target,user,password);var sql=c.createStatement()){sql.execute("INSERT INTO cinenest_rooms.venue(venue_id,code,display_name,timezone) VALUES('00000000-0000-4000-8000-000000000001','KEEP','Retained V18','Asia/Colombo')");sql.execute("INSERT INTO cinenest_booking.hold_policy VALUES('00000000-0000-4000-8000-000000000002',600,10,60,'SYNTHETIC upgrade',clock_timestamp())");sql.execute("INSERT INTO cinenest_booking.inventory_block VALUES('00000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000004','2026-10-21T00:00:00Z','2026-10-21T03:00:00Z',0,'2026-10-21T03:00:00Z',FALSE,'CONFIRMED',0)");sql.execute("INSERT INTO cinenest_booking.reservation_hold VALUES('00000000-0000-4000-8000-000000000005','00000000-0000-4000-8000-000000000006','00000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000002',4,'SYNTHETIC','Asia/Colombo','SYNTHETIC',clock_timestamp(),clock_timestamp()+INTERVAL '1 hour','RELEASED',0)");sql.execute("INSERT INTO cinenest_booking.booking VALUES('00000000-0000-4000-8000-000000000007','00000000-0000-4000-8000-000000000008','00000000-0000-4000-8000-000000000005','00000000-0000-4000-8000-000000000006','00000000-0000-4000-8000-000000000001','SIMULATED_CONFIRMED',TRUE,clock_timestamp())");sql.execute("INSERT INTO cinenest_booking.booking_revision VALUES('00000000-0000-4000-8000-000000000007',1,'00000000-0000-4000-8000-000000000009',1,repeat('a',64),10000,'LKR','{\"synthetic\":true,\"commercialIssuance\":false,\"marker\":\"SYNTHETIC-RETAINED-V18\"}')");}var f=Flyway.configure().dataSource(target,user,password).target("19").load();assertThat(f.migrate().migrationsExecuted).isEqualTo(1);assertThat(f.migrate().migrationsExecuted).isZero();f.validate();try(var c=DriverManager.getConnection(target,user,password);var sql=c.createStatement();var rows=sql.executeQuery("SELECT display_name FROM cinenest_rooms.venue")){assertThat(rows.next()).isTrue();assertThat(rows.getString(1)).isEqualTo("Retained V18");try(var retained=sql.executeQuery("SELECT snapshot->>'marker' FROM cinenest_booking.booking_revision")){assertThat(retained.next()).isTrue();assertThat(retained.getString(1)).isEqualTo("SYNTHETIC-RETAINED-V18");}}}finally{try(var c=DriverManager.getConnection(url,user,password);var sql=c.createStatement()){sql.execute("DROP DATABASE "+database+" WITH (FORCE)");}}
    }

